6	import org.springframework.data.domain.Page;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
9	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
11	
12	import java.util.Collection;
13	import java.util.List;
14	
15	/**
16	 * Maps Owner & OwnerDto using Mapstruct
17	 */
18	@Mapper(uses = PetMapper.class)
19	public interface OwnerMapper {
20	
21	    @Mapping(target = "displayName", expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
22	    @Mapping(target = "initials", expression = "java(Character.toUpperCase(owner.getFirstName().charAt(0)) + \".\" + Character.toUpperCase(owner.getLastName().charAt(0)) + \".\")")
23	    @Mapping(target = "membershipNumber", expression = "java(toMembershipNumber(owner))")
24	    @Mapping(target = "checkDigit", expression = "java(toCheckDigit(owner))")
25	    @Mapping(target = "membershipPoints", expression = "java(toMembershipPoints(owner))")
26	    @Mapping(target = "membershipLevel", expression = "java(toMembershipLevel(owner))")
27	    @Mapping(target = "locality", expression = "java(toLocality(owner))")
28	    @Mapping(target = "contactPreference", expression = "java(toContactPreference(owner))")
29	    @Mapping(target = "identityKey", expression = "java(toIdentityKey(owner))")
30	    @Mapping(target = "ageBand", expression = "java(toAgeBand(owner))")
31	    @Mapping(target = "telephoneDisplay", expression = "java(toTelephoneDisplay(owner))")
32	    OwnerDto toOwnerDto(Owner owner);
33	
34	    /**
35	     * Derives the owner's {@code telephoneDisplay}: the stored E.164 {@code telephone} formatted
36	     * for humans (see {@link org.springframework.samples.petclinic.rest.function.owner.E164Telephone#display}).
37	     * The raw {@code telephone} is left in E.164 form.
38	     */
39	    default String toTelephoneDisplay(Owner owner) {
40	        return org.springframework.samples.petclinic.rest.function.owner.E164Telephone
41	                .display(owner.getTelephone());
42	    }
43	
44	    /**
45	     * Derives the owner's {@code ageBand} from its {@code birthDate} measured against its
46	     * {@code registrationDate}: {@code MINOR} when under 18, {@code ADULT} from 18 to 64,
47	     * {@code SENIOR} at 65 or older. Returns null when either date is absent (so no band is
48	     * reported for owners with no supplied birth date).
49	     */
50	    default org.springframework.samples.petclinic.rest.dto.OwnerDto.AgeBandEnum toAgeBand(Owner owner) {
51	        java.time.LocalDate birthDate = owner.getBirthDate();
52	        java.time.LocalDate registrationDate = owner.getRegistrationDate();
53	        if (birthDate == null || registrationDate == null) {
54	            return null;
55	        }
56	        int age = java.time.Period.between(birthDate, registrationDate).getYears();
57	        if (age < 18) {
58	            return org.springframework.samples.petclinic.rest.dto.OwnerDto.AgeBandEnum.MINOR;
59	        }
60	        if (age < 65) {
61	            return org.springframework.samples.petclinic.rest.dto.OwnerDto.AgeBandEnum.ADULT;
62	        }
63	        return org.springframework.samples.petclinic.rest.dto.OwnerDto.AgeBandEnum.SENIOR;
64	    }
65	
66	    /**
67	     * Derives the owner's {@code identityKey}: the single value that consolidates all
68	     * duplicate detection, {@code normalizedTelephone + '|' + (email or empty) + '|' +
69	     * (householdId or empty)}.
70	     */
71	    default String toIdentityKey(Owner owner) {
72	        return org.springframework.samples.petclinic.rest.function.owner.OwnerIdentity.key(owner);
73	    }
74	
75	    /**
76	     * Derives the owner's preferred contact channel: {@code EMAIL} when an email is present,
77	     * otherwise {@code PHONE}.
78	     */
79	    default String toContactPreference(Owner owner) {
80	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
81	        return hasEmail ? "EMAIL" : "PHONE";
82	    }
83	
84	    /**
85	     * Derives the owner's locality (region) from its region-and-hash identity: the
86	     * {@code customerCode} is {@code <REGION>-<HASH8>}, so the locality is the REGION segment
87	     * preceding the hash. Falls back to deriving the region directly from the postcode/city
88	     * (see {@link org.springframework.samples.petclinic.rest.function.owner.OwnerCustomerCode})
89	     * only for unmigrated owners that carry no customer code.
90	     */
91	    default String toLocality(Owner owner) {
92	        String customerCode = owner.getCustomerCode();
93	        if (customerCode != null) {
94	            int dash = customerCode.indexOf('-');
95	            if (dash > 0) {
96	                return customerCode.substring(0, dash);
97	            }
98	        }
99	        return org.springframework.samples.petclinic.rest.function.owner.OwnerCustomerCode
100	                .region(owner.getPostcode(), owner.getCity());
101	    }
102	
103	    /**
104	     * Derives the owner's membership points: start at 0; add 2 when an email is present; add 1
105	     * when the owner has no namesakes ({@code namesakeCount} is 0); add 2 for a household of 3 or
106	     * more ({@code householdSize} at least 3); add 3 for tenure over 365 days (a
107	     * {@code registrationDate} more than 365 days ago). A newly created owner has zero tenure.
108	     */
109	    default Integer toMembershipPoints(Owner owner) {
110	        int points = 0;
111	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
112	        if (hasEmail) {
113	            points += 2;
114	        }
115	        boolean unique = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
116	        if (unique) {
117	            points += 1;
118	        }
119	        if (owner.getHouseholdSize() != null && owner.getHouseholdSize() >= 3) {
120	            points += 2;
121	        }
122	        java.time.LocalDate registrationDate = owner.getRegistrationDate();
123	        if (registrationDate != null && java.time.temporal.ChronoUnit.DAYS
124	                .between(registrationDate, java.time.LocalDate.now()) > 365) {
125	            points += 3;
126	        }
127	        return points;
128	    }
129	
130	    /**
131	     * Derives the owner's numeric membership level (1 to 4) from its {@code membershipPoints}:
132	     * level 1 for 0-1 points, 2 for 2-3, 3 for 4-5, 4 for 6 or more.
133	     */
134	    default Integer toMembershipLevel(Owner owner) {
135	        int points = toMembershipPoints(owner);
136	        if (points >= 6) {
137	            return 4;
138	        }
139	        if (points >= 4) {
140	            return 3;
141	        }
142	        if (points >= 2) {
143	            return 2;
144	        }
145	        return 1;
146	    }
147	
148	    /**
149	     * Derives the owner's membership number as {@code <customerCode>-M<YY>}, where YY is the
150	     * last two digits of the registration-date year (e.g. {@code NSW-1A2B3C4D-M26}). Returns
151	     * null when either the customer code or registration date is absent (e.g. unmigrated seed
152	     * data).
